&reftitle.description;
public static boolSwoole\Event::cycle callablecallback boolbeforefalse
Метод задаёт функцию обратного вызова, которую выполняют в конце каждой итерации цикла событий, а если параметру before передали значение true — то в начале.

  &reftitle.examples;



    Базовый пример использования


<?php
Swoole\Timer::tick(2000, function ($id) {
    var_dump($id);
});

Swoole\Event::cycle(function () {
    echo "hello [1]\n";
    Swoole\Event::cycle(function () {
        echo "hello [2]\n";
        Swoole\Event::cycle(null);
    });
});

Swoole\Event::wait();
